<script setup lang="ts">import {ref}from'vue';import{useI18n}from'vue-i18n';const{locale}=useI18n();const capacity=ref(2);const jobs=ref(4)</script>
<template><article><section class="detail-hero"><p class="eyebrow">{{locale==='fa'?'واژه‌نامه و محیط آزمایش':'Glossary and playground'}}</p><h1>{{locale==='fa'?'مفاهیم هماهنگی':'Concurrency primitives'}}</h1><p>{{locale==='fa'?'primitive را از روی قانونی که محافظت می‌کند انتخاب کنید، نه از روی نام آن.':'Choose a primitive from the invariant it protects, not from its name.'}}</p></section><section class="lesson-content"><div class="glossary-grid"><article><h2>Latest wins</h2><p>{{locale==='fa'?'فقط جدیدترین قصد اجازهٔ ثبت دارد.':'Only the newest intent may commit.'}}</p></article><article><h2>Mutex</h2><p>{{locale==='fa'?'یک مالک؛ حذف تکرار سیاست جداگانه است.':'One owner; deduplication is separate.'}}</p></article><article><h2>Semaphore</h2><p>{{locale==='fa'?'حداکثر N کار فعال و صف FIFO.':'At most N active jobs and a FIFO queue.'}}</p></article><article><h2>Single-flight</h2><p>{{locale==='fa'?'یک producer در حال اجرا برای هر کلید؛ cache نیست.':'One in-flight producer per key; not a cache.'}}</p></article></div><section class="comparison-controls"><h2>{{locale==='fa'?'محیط permit':'Permit playground'}}</h2><label>{{locale==='fa'?'ظرفیت':'Capacity'}} <input v-model.number="capacity" type="range" min="1" max="4" /></label><label>{{locale==='fa'?'کارها':'Jobs'}} <input v-model.number="jobs" type="range" min="1" max="8" /></label><p>{{locale==='fa'?'فعال':'Active'}}: {{Math.min(capacity,jobs)}} · {{locale==='fa'?'در صف':'Queued'}}: {{Math.max(0,jobs-capacity)}} · {{locale==='fa'?'آزاد':'Available'}}: {{Math.max(0,capacity-jobs)}}</p></section></section></article></template>
